//! The broker's settings, shared by their readers and command-line help.

hatchling_core::declare_environment! {
    pub,
    HATCHLING_BROKER_SOCKET: ("required", "Absolute agent socket when serving without a cell; a cell's agent gets its own connection."),
    HATCHLING_AGENT_UID: ("required", "Only host uid allowed to connect; equals the cell's mapped uid."),
    HATCHLING_AGENT_ALLOW_NOBODY: ("optional; default false", "Accept nobody (65534) as the agent uid: true/1 or false/0; any nobody process could act as the agent."),
    HATCHLING_BROKER_SOCKET_MODE: ("optional; default 600", "Socket permissions as an octal Unix mode."),
    HATCHLING_BROKER_MAX_CONNECTIONS: ("optional", "Maximum simultaneous broker connections."),
    HATCHLING_LOG_LEVEL: ("optional; default info", "Log verbosity: error, warn, info, debug or trace."),
    HATCHLING_VAULT_DIR: ("required", "Absolute root of the sealed credential vault."),
    HATCHLING_VAULT_KEY_FILE: ("optional", "Master-key file; defaults to an owner-only sibling keys directory."),
    HATCHLING_VAULT_GRANTS: ("optional; default none", "Comma-separated permitted vault action:name grants."),
    HATCHLING_VAULT_KEYRING: ("optional", "Absolute vault keyring path, instead of a bare master key."),
    HATCHLING_VAULT_KEK_FILE: ("optional", "Absolute file wrapping-key path for the keyring's file tier."),
    HATCHLING_REQUIRE_HARDWARE_KEY: ("optional; default false", "Require the keyring's hardware-key tier."),
    HATCHLING_EGRESS_ALLOWLIST: ("optional; default none", "Allowed host:port destinations and local/local-keyless qualifiers."),
    HATCHLING_EGRESS_GRANTS: ("optional; default none", "Comma-separated host:port destinations this agent may request."),
    HATCHLING_EGRESS_CA_BUNDLE: ("optional", "Absolute PEM bundle of additional trusted HTTPS roots."),
    HATCHLING_CHANNELS: ("optional; default local", "Comma-separated enabled channel identifiers."),
    HATCHLING_CHANNEL_ACCOUNTS: ("optional", "Channel account credentials as channel:label=secret-name."),
    HATCHLING_CHANNEL_INGRESS: ("optional", "Absolute local-channel ingress socket, outside the cell's socket directory."),
    HATCHLING_SKILLS_DIR: ("optional; default disabled", "Absolute directory of signed skill manifests."),
    HATCHLING_SKILL_TRUST_ROOTS: ("required with skills", "Absolute file of skill-signing trust roots."),
    HATCHLING_SKILL_TRUST_ROOT: ("obsolete; must be unset", "Rejected inline signing key; use HATCHLING_SKILL_TRUST_ROOTS."),
    HATCHLING_SKILL_GRANTS: ("optional; default none", "Comma-separated skill:capability grants."),
    HATCHLING_MEMORY_DIR: ("optional; default disabled", "Absolute memory-store root."),
    HATCHLING_MEMORY_GRANTS: ("optional; default none", "Comma-separated memory scope:action grants."),
    HATCHLING_GOALS_DIR: ("optional; default disabled", "Absolute goals and tracking store root."),
    HATCHLING_GOALS_GRANTS: ("optional; default none", "Comma-separated goals capability grants."),
    HATCHLING_SCHEDULER_DIR: ("optional; default disabled", "Absolute sealed schedule-store root."),
    HATCHLING_SCHEDULER_MODEL_ENDPOINT: ("optional", "Model API base URL supplied to scheduled run cells."),
    HATCHLING_SCHEDULER_MODEL_NAME: ("optional", "Provider model identifier supplied to scheduled runs."),
    HATCHLING_SCHEDULER_MODEL_REASONING: ("optional; default provider-default", "Thinking mode supplied to scheduled and child runs: provider-default or disabled."),
    HATCHLING_ARTIFACT_DIR: ("optional; default disabled", "Absolute sealed artifact build-store root."),
    HATCHLING_ARTIFACT_WORKSPACE: ("required with a configured harness", "Absolute workspace destination for approved deliveries."),
    HATCHLING_ARTIFACT_DENY: ("optional", "Comma-separated output categories the review policy refuses."),
    HATCHLING_ARTIFACT_MAX_BYTES: ("optional", "Maximum delivery size in bytes for the share-review policy."),
    HATCHLING_SPACE_DIR: ("optional; default disabled", "Absolute sealed space-store root."),
    HATCHLING_DEVICE_SOCKET: ("optional", "Absolute socket for paired device connections."),
    HATCHLING_AGENT_BIN: ("optional; enables cell spawning", "Absolute agent executable path; may point at hatchling."),
    HATCHLING_CELL_ID: ("required when spawning an agent", "Identity supplied to the initial agent cell."),
    HATCHLING_CELL_UID_BASE: ("optional", "Host uid mapped into the cell; must match HATCHLING_AGENT_UID."),
    HATCHLING_CELL_UID_COUNT: ("optional; default 1", "Number of uids mapped into the cell."),
    HATCHLING_CELL_MAX_PROCESSES: ("optional; default 4096", "Process/thread limit; positive count or unlimited; aggregate with cgroups."),
    HATCHLING_CELL_MAX_ADDRESS_SPACE: ("optional; default unlimited", "Per-process address-space limit in bytes or unlimited."),
    HATCHLING_CELL_MAX_FILE_SIZE: ("optional; default 8589934592", "Per-file size limit in bytes or unlimited."),
    HATCHLING_CELL_MAX_OPEN_FILES: ("optional; default 8192", "Per-process open-file limit or unlimited."),
    HATCHLING_CELL_CGROUP: ("optional", "Delegated cgroup v2 parent; unset uses the rlimit fallback."),
    HATCHLING_CELL_MAX_MEMORY: ("optional", "Whole-cell bytes or unlimited; cgroup default is half the effective memory limit."),
    HATCHLING_CELL_MAX_CPUS: ("optional; default unlimited", "Whole-cell fractional core allowance; only effective with a cgroup."),
    HATCHLING_API_SOCKET: ("optional; enables the local API", "Absolute API socket outside the cell's socket directory; requires the schedule activity log."),
    HATCHLING_API_GRANTS: ("optional; default none", "Comma-separated local API grant labels; each must be held by the owner."),
    HATCHLING_UI_SOCKET: ("optional; enables the UI socket", "Absolute UI socket for hatchling-host; callers present the token in <socket>.token."),
    HATCHLING_OPERATOR_SOCKET: ("optional; enables the operator socket", "Absolute operator socket, read-only machine metadata; callers present the token in <socket>.token."),
    HATCHLING_API_NETWORK: ("optional; refused in this build", "Requested network API address; this build has no token provider and never enables it."),
    HATCHLING_API_ALLOW_NETWORK: ("optional; default false", "Network API acknowledgement: true/1 or false/0; does not enable a listener in this build."),
    HATCHLING_HARNESS_CLAUDE_CODE: ("optional; paired with its SHA256", "Absolute pinned Claude Code executable path."),
    HATCHLING_HARNESS_CLAUDE_CODE_SHA256: ("required with CLAUDE_CODE", "SHA-256 of the configured Claude Code executable."),
    HATCHLING_HARNESS_CLAUDE_CODE_API: ("optional", "Claude Code vendor API allowlist; unset runs the harness offline."),
    HATCHLING_HARNESS_CODEX_CLI: ("optional; paired with its SHA256", "Absolute pinned Codex CLI executable path."),
    HATCHLING_HARNESS_CODEX_CLI_SHA256: ("required with CODEX_CLI", "SHA-256 of the configured Codex CLI executable."),
    HATCHLING_HARNESS_CODEX_CLI_API: ("optional", "Codex CLI vendor API allowlist; unset runs the harness offline."),
    HATCHLING_HARNESS_CODEX_CLI_HOST: ("optional, paired with CODEX_CLI_HOST_SHA256", "Absolute pinned CLI host executable path."),
    HATCHLING_HARNESS_CODEX_CLI_HOST_SHA256: ("required with CODEX_CLI_HOST", "SHA-256 of the configured CLI host executable."),
    HATCHLING_HARNESS_TOOLS: ("optional", "Comma-separated absolute tool paths; networked harnesses default to available standard tools, explicit paths need a vendor API."),
    HATCHLING_HARNESS_ROOTS: ("required with a configured harness", "Permitted host roots for harness work trees."),
    HATCHLING_HARNESS_TIMEOUT_SECS: ("optional", "Harness execution deadline in seconds."),
    HATCHLING_OUTPUT_GATE: ("optional; default on", "Local-channel output review, on or off."),
    HATCHLING_REDACTION_KEEP_RAW: ("optional; default false", "Keep encrypted original output for operator review: true/1 or false/0."),
    HATCHLING_REDACTION_TIMEOUT_MS: ("optional", "Output review deadline in milliseconds."),
    HATCHLING_REDACTION_DIR: ("optional", "Absolute output-review log and override directory."),
    HATCHLING_REDACTION_BUILTINS: ("optional", "Built-in categories checked by output review."),
}
